    traits: ["Athamaru","Primal"],
    rarity: "common",
    provenance: { type: 'official' },
    description: `With a flick of your tail, you direct the water around you to move creatures. You move water in a 20-foot line; this line must be entirely in water. Each creature in this line must attempt a Fortitude save against your class DC or spell DC, whichever is higher. A creature can choose to fail the save.

**Critical Success** The creature is unaffected.
**Success** The creature is pushed or pulled 5 feet in the direction of your choice. All creatures must be moved in the same direction.
**Failure** As success, but the creature is pushed or pulled 10 feet.
**Critical Failure** As success, but the creature is pushed or pulled 10 feet, and the creature is off-guard until the end of your next turn.`,
