    provenance: { type: 'official' },
    description: `Cooperation and coordination are the secrets to getting by in tanuki society. When the triggering ally transforms, you Stride to their square and join shape with them, melding into their transformation. While you’re melded in this way, you grant them the effects of either a 2nd- or 4th‑rank _enlarge_ spell as well as temporary Hit Points equal to your level; if their polymorph effect would normally grant them temporary Hit Points, you increase the amount by your level instead. While you’re melded, you can’t be separately targeted and you can’t act except to speak or to use Change Shape to exit the Combined Form, which ends the effects of enlarge on your ally and removes any remaining temporary Hit Points they received from this ability at the time. If the triggering ally becomes unconscious or the triggering polymorph effect ends, you automatically exit the Combined Form.`,
