    traits: ["Tanuki"],
    rarity: "common",
    provenance: { type: 'official' },
    description: `While walking down the road on a moonlit night, one might be puzzled to find a shop or hill that wasn’t there before. In reality, this is a tanuki at the height of their power. When you Change Shape, you can transform into a building or terrain feature up to 50 feet tall and up to 50 feet on a side. Mundane features of your landscape form function as normal—for instance, if you transform into a hot spring, the hot spring contains relaxing hot water, and if you transform into an inn, the inn contains bedrooms, beds, and delicious food—though no aspect of your landscape form can be an active hazard that can cause damage or impose conditions, and any objects created within your landscape form turn into leaves if taken outside of it. You can speak while in landscape form, but you can’t attack, cast spells, or move. You can remain in landscape form for up to 8 hours, and when you exit landscape form, it dissolves around anyone who was inside of it.`,
